Winding number alg:
See https://users.cs.utah.edu/~ladislav/jacobson13robust/jacobson13robust.pdf
```	
		while (r_points.size() < emissor_count && attempts < max_attempts) {
			attempts++;

			// Random point inside bounding box
			Vector3 candidate_point = Vector3(Math::randf(), Math::randf(), Math::randf()) * aabb.size + aabb.position;

			// Calculate winding number for candidate_point p
			// W(p) = (1 / 4*PI) * sum(omega)
			// omega = det(A,B,C) / (lenA*lenB*lenC + A.B*lenC + B.C*lenA + C.A*lenB)
			double total_winding_number = 0.0;

			for (int i = 0; i < face_count; i++) {
				// Vectors from candidate_point to the triangle vertices
				Vector3 a = faces[i].vertex[0] - candidate_point;
				Vector3 b = faces[i].vertex[1] - candidate_point;
				Vector3 c = faces[i].vertex[2] - candidate_point;

				double al = a.length();
				double bl = b.length();
				double cl = c.length();

				// det(A,B,C) = a.(b x c)
				double det = a.dot(b.cross(c));
				double denom = al * bl * cl + a.dot(b) * cl + b.dot(c) * al + c.dot(a) * bl;

				// omega = 2 * atan2(y,x)
				total_winding_number += 2.0 * Math::atan2(det, denom);
			}

			total_winding_number /= (4.0 * Math::PI);

			if (Math::abs(total_winding_number) > 0.5) {
				r_points.push_back(candidate_point);
			}
		}
```
